        let values = [canvasRound(unit.x), canvasRound(unit.y)]
        switch endpoint {
        case .from: return .setShape(clips: [clip], patch: ShapePatch(from: values))
        case .to: return .setShape(clips: [clip], patch: ShapePatch(to: values))
